import{_ as d,o,c as e,ak as a}from"./chunks/framework.DKi5cyCJ.js";const g=JSON.parse('{"title":"手册前提与深水区","description":"对驱动面试手册的限定条件，以及 UART、看门狗、Modbus、低功耗和 volatile 的追问边界","frontmatter":{"title":"手册前提与深水区","description":"对驱动面试手册的限定条件，以及 UART、看门狗、Modbus、低功耗和 volatile 的追问边界","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-手册前提与深水区.md","filePath":"pages/blog/2026-10-21-手册前提与深水区.md"}'),r={name:"pages/blog/2026-10-21-手册前提与深水区.md"};function c(s,t,p,n,l,_){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="手册前提与深水区" tabindex="-1">手册前提与深水区 <a class="header-anchor" href="#手册前提与深水区" aria-label="Permalink to &quot;手册前提与深水区&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a></p></blockquote><p>下面这些条目原手册的方向是对的，面试时要主动补上前提，避免被追问成“绝对成立”。</p><h2 id="需要限定的表述" tabindex="-1">需要限定的表述 <a class="header-anchor" href="#需要限定的表述" aria-label="Permalink to &quot;需要限定的表述&quot;">​</a></h2><table tabindex="0"><thead><tr><th>原表述</th><th>更稳妥的说法</th></tr></thead><tbody><tr><td>1 Mbit/s 干线约 25 m</td><td>支线通常 ≤ 0.3 m。干线经验值在 25–40 m，还受线缆、节点数和终端质量影响</td></tr><tr><td>日志用高 CAN ID 所以优先级低</td><td>优先级只由 ID 数值决定。高 ID 是应用层故意让日志让路，不是协议分类</td></tr><tr><td>I2C 100 kHz 就用 4.7 kΩ</td><td>总线电容接近 400 pF 时，4.7 kΩ 的上升时间可能超标。电阻下限看灌电流，上限看 <code>tr / (0.8473 × Cb)</code></td></tr><tr><td>SPI 模式差 1 就整体错 1 位</td><td>常见是错位或首 bit 错，低速时也可能时好时坏，不能说必然错 1 位。读命令标志以从机手册为准</td></tr><tr><td>RMII 只能有一个时钟源</td><td>MAC 和 PHY 必须共用同一个 50 MHz REF_CLK，来源可以是 MCU、PHY 或外部晶振，但全链路只能有一个</td></tr><tr><td>死区 DTG=84 在 168 MHz 下是 0.5 µs</td><td>按 STM32F4 第一档编码，84 × (1/168 MHz) ≈ 500 ns。换系列先查 DTG 分档表。死区越大越不容易直通，但会吃掉有效占空比</td></tr><tr><td>栈顶掩码 <code>0x2FFE0000</code></td><td>只适合 SRAM 从 <code>0x20000000</code> 起、大约 128 KB 的型号。F7/H7 不能套用</td></tr><tr><td><code>.data</code> 拷贝边界</td><td>来自链接脚本的 <code>_sidata</code>、<code>_sdata</code>、<code>_edata</code></td></tr><tr><td>接收前 Invalidate</td><td>必须在启动 DMA 之前做完。DMA 已经在写之后再作废，可能丢掉刚写入的数据</td></tr><tr><td>定时器时钟 ×2</td><td>是 STM32F1/F4 一类的典型时钟树。换系列先查参考手册</td></tr><tr><td>NDTR</td><td>是数据项个数。半字宽度时 NDTR=10 是 20 字节</td></tr></tbody></table><p>9 个 SCL 脉冲后 SDA 仍为低：继续发脉冲，必要时给从机断电再上电。</p><h2 id="追问时怎么往下答" tabindex="-1">追问时怎么往下答 <a class="header-anchor" href="#追问时怎么往下答" aria-label="Permalink to &quot;追问时怎么往下答&quot;">​</a></h2><p><strong>UART。</strong> 误差大约超过 2%–3% 会误码。115200 乱码要查时钟能不能被波特率整除，不只说“配错了”。RS485 切回接收必须等 TC。自动收发电路省掉 GPIO，高速长线仍要核对切换延迟。</p><p><strong>I2C / SPI。</strong> 设备变多、电容变大，上拉要减小，同时不能小到灌电流超标。SPI 的 <code>tCSS</code>、<code>tCSH</code> 在时序图里，不在寄存器说明正文里。</p><p><strong>CAN。</strong> 位填充从 SOF 到 CRC 序列，连续 5 个相同位插一个反相，用来给重同步提供边沿。节点频繁掉线而线束正常时，查 TEC/REC 是否已经 Bus-Off。</p><p><strong>ADC。</strong> 采样是给内部采样电容充电。高阻输入要加长采样时间，或加跟随器。过采样每 4 倍大约多 1 位，前提是噪声接近白噪声。32 次不是无限提高精度。</p><p><strong>看门狗。</strong> 不要在定时器中断里喂狗：主循环死了，中断还在喂，狗永远不咬。IWDG 用 LSI，启动后软件关不掉。WWDG 用 PCLK，喂早了或喂晚了都会复位。</p><p><strong>Modbus RTU。</strong> 帧尾是 3.5 个字符时间的静默，不是固定帧头。多字节是大端。半双工同样要等 UART 的 TC 再切方向。</p><p><strong>低功耗。</strong> Sleep 只停 CPU。Stop 停时钟但保留 SRAM。Standby 几乎断电，SRAM 丢失，唤醒类似复位。要保留现场或快速恢复时用 Stop。</p><p><strong>volatile。</strong> 对寄存器必须加，保证每次从内存访问。它不保证原子性，也不代替内存屏障。改寄存器某一位用读-改-写加掩码；有“写 1 清零”语义的位不能裸或、裸与。</p><p><strong>Linux 字符设备。</strong> <code>file_operations</code> → 设备号 → <code>cdev</code> → 设备节点。用户指针必须 <code>copy_to_user</code> / <code>copy_from_user</code>。设备树靠 <code>compatible</code> 匹配后进 <code>probe</code>；<code>status = &quot;okay&quot;</code> 才会用。优先用 <code>devm_</code> 资源，失败时看 <code>dmesg</code> 里是 <code>-EPROBE_DEFER</code> 还是 <code>-ENODEV</code>。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',17)])])}const b=d(r,[["render",c]]);export{g as __pageData,b as default};
